<?php
declare(strict_types=1); session_start();
const APP_TITLE='After Dark'; const DEFAULT_ADMIN_PASSWORD='datenight';
$loadAdminScript=isset($_GET['admin']);
header('X-Robots-Tag: noindex, nofollow, noarchive, nosnippet');
ob_start(static function(string $html)use($loadAdminScript):string{$html=str_replace('<head>','<head><meta name="robots" content="noindex,nofollow,noarchive,nosnippet">',$html);return $loadAdminScript?str_replace('</body>','<script src="assets/app.js?v=2" defer></script></body>',$html):$html;});
function db():PDO{static $d;if($d)return $d;$dir=__DIR__.'/data';if(!is_dir($dir))mkdir($dir,0775,true);$d=new PDO('sqlite:'.$dir.'/datenights.sqlite');$d->setAttribute(PDO::ATTR_ERRMODE,PDO::ERRMODE_EXCEPTION);$d->setAttribute(PDO::ATTR_DEFAULT_FETCH_MODE,PDO::FETCH_ASSOC);$d->exec("CREATE TABLE IF NOT EXISTS ideas(id INTEGER PRIMARY KEY AUTOINCREMENT,title TEXT NOT NULL,content TEXT NOT NULL DEFAULT '',active INTEGER NOT NULL DEFAULT 1,created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP)");if(!(int)$d->query('SELECT COUNT(*) FROM ideas')->fetchColumn()){$ideas=[['Pose Game','<p>Strike a pose, lose your inhibitions.</p><p><a href="https://pose-game.cc/">Open Pose Game</a></p>'],['Lovia','<p>A playful little detour for two.</p><p><a href="https://www.lovia.rocks/">Open Lovia</a></p>'],['Bondly Cards','<p>Pick a card. Get closer.</p><p><a href="https://bondlycards.com/">Open Bondly Cards</a></p>'],['Vorlieben Matches','<p>Find out where your desires overlap.</p><p><a href="https://vorlieben-matches.llsm.de/">Start matching</a></p>'],['That Sex Quiz','<p>How well do we really know each other?</p><p><a href="https://www.thatsexquiz.com/">Take the quiz</a></p>'],['The Foreplay Game','<p>No rushing tonight.</p><p><a href="https://www.theforeplaygame.com/">Play the game</a></p>'],['Unspeakable Things','<p>Say the things you usually only think.</p><p><a href="https://playunspeakablethings.com/">Play Unspeakable Things</a></p>'],['Jade Green','<p>A mystery waiting behind one click.</p><p><a href="https://jadegreen.lima.zone/">Open Jade Green</a></p>'],['Sexy Harness Shopping','<h2>Choose something irresistible</h2><ul><li><a href="https://www.hunkemoller.ch/search?q=harness">Hunkemöller</a></li><li><a href="https://www.annsummers.com/">Ann Summers</a></li><li><a href="https://madamepierre.ch/">Madame Pierre</a></li><li><a href="https://www.sedusia.ch/">Sedusia</a></li><li><a href="https://www.bluebella.eu/">Bluebella</a></li><li><a href="https://mariemur.com/">Mariemur</a></li><li><a href="https://www.drharness.co/">Dr Harness</a></li><li><a href="https://fatale-manner.com/">Fatale Manner</a></li><li><a href="https://erocult.com/">Erocult</a></li><li><a href="https://scandale.com">Scandale</a></li></ul>']];$s=$d->prepare('INSERT INTO ideas(title,content)VALUES(?,?)');foreach($ideas as $i)$s->execute($i);}return $d;}
function e(string $s):string{return htmlspecialchars($s,ENT_QUOTES|ENT_SUBSTITUTE,'UTF-8');}function csrf():string{if(empty($_SESSION['csrf']))$_SESSION['csrf']=bin2hex(random_bytes(24));return $_SESSION['csrf'];}function isAdmin():bool{return !empty($_SESSION['admin']);}
function clean(string $h):string{$h=strip_tags($h,'<p><br><strong><b><h2><ul><li><a>');$h=preg_replace('/<(p|br|strong|b|h2|ul|li)\b[^>]*>/i','<$1>',$h)??'';return preg_replace_callback('/<a\s+[^>]*href\s*=\s*(["\'])(.*?)\1[^>]*>/i',function($m){$u=trim(html_entity_decode($m[2],ENT_QUOTES,'UTF-8'));return preg_match('~^https?://~i',$u)?'<a href="'.e($u).'" target="_blank" rel="noopener noreferrer">':'<a>';},$h)??'';}
$admin=isset($_GET['admin']);$error='';if($admin&&$_SERVER['REQUEST_METHOD']==='POST'){$a=$_POST['action']??'';if($a==='login'){$pw=getenv('DATENIGHT_ADMIN_PASSWORD')?:DEFAULT_ADMIN_PASSWORD;if(hash_equals($pw,(string)($_POST['password']??''))){session_regenerate_id(true);$_SESSION['admin']=true;csrf();header('Location:?admin=1');exit;}$error='That wasn’t the password.';}elseif($a==='logout'&&isAdmin()){$_SESSION=[];session_destroy();header('Location:./');exit;}elseif(isAdmin()&&hash_equals(csrf(),(string)($_POST['csrf']??''))){if($a==='save'){$id=(int)($_POST['id']??0);$t=trim((string)($_POST['title']??''));$c=clean((string)($_POST['content']??''));$on=isset($_POST['active'])?1:0;if($t!==''){if($id){$s=db()->prepare('UPDATE ideas SET title=?,content=?,active=?,updated_at=CURRENT_TIMESTAMP WHERE id=?');$s->execute([$t,$c,$on,$id]);}else{$s=db()->prepare('INSERT INTO ideas(title,content,active)VALUES(?,?,?)');$s->execute([$t,$c,$on]);}}}elseif($a==='delete'){$s=db()->prepare('DELETE FROM ideas WHERE id=?');$s->execute([(int)($_POST['id']??0)]);}header('Location:?admin=1');exit;}}
$ideas=db()->query('SELECT id,title,content FROM ideas WHERE active=1 ORDER BY id')->fetchAll();$all=$admin&&isAdmin()?db()->query('SELECT * FROM ideas ORDER BY id')->fetchAll():[];
function editor(array $i):string{$id=(int)$i['id'];ob_start();?><form method="post" class="editor-form" data-editor-form><input type="hidden" name="action" value="save"><input type="hidden" name="csrf" value="<?=e(csrf())?>"><input type="hidden" name="id" value="<?=$id?>"><input type="hidden" name="content" value="<?=e((string)$i['content'])?>" data-content-input><label>Card front<input name="title" value="<?=e((string)$i['title'])?>" maxlength="100" placeholder="Give it a tempting title" required></label><div class="field-label">Card back</div><div class="toolbar" role="toolbar" aria-label="Formatting"><button type="button" data-command="bold"><b>B</b></button><button type="button" data-command="formatBlock" data-value="h2">H</button><button type="button" data-command="insertUnorderedList">• List</button><button type="button" data-command="createLink">↗ Link</button></div><div class="rich-editor" contenteditable="true" role="textbox" aria-multiline="true" data-editor><?=$i['content']?></div><div class="form-actions"><label class="toggle"><input type="checkbox" name="active" <?=$i['active']?'checked':''?>><span></span> In deck</label><button class="primary-button small" type="submit"><?=$id?'Save changes':'Add to deck'?></button></div></form><?php if($id):?><form method="post" class="delete-form" onsubmit="return confirm('Remove this idea forever?')"><input type="hidden" name="action" value="delete"><input type="hidden" name="csrf" value="<?=e(csrf())?>"><input type="hidden" name="id" value="<?=$id?>"><button class="delete-button">Delete idea</button></form><?php endif;return(string)ob_get_clean();}
