<?php else:?><main class="app-shell"><header class="masthead"><div class="monogram" aria-hidden="true">A<span>×</span>A</div><p>Our private collection</p></header><section class="experience" aria-labelledby="page-title"><div class="intro"><p class="eyebrow">Tonight’s invitation</p><h1 id="page-title">Leave it<br>to <em>chance.</em></h1><p class="lede">One night. One card.<br>No overthinking.</p></div><div class="stage" id="stage" aria-live="polite"><div class="ambient-glow"></div><div class="deck"><div class="ghost-card ghost-one"></div><div class="ghost-card ghost-two"></div><article class="date-card" id="date-card"><div class="card-face card-front"><div class="card-ornament">✦</div><p class="card-kicker">A date for two</p><h2 id="card-title">Ready to tempt fate?</h2><span class="card-number">№ <b id="card-number">?</b></span></div><div class="card-face card-back"><button class="close-card" id="close-card" aria-label="Turn card over">×</button><p class="card-kicker">Tonight</p><h2 id="result-title"></h2><div class="card-content" id="result-content"></div></div></article></div><p class="shuffle-status" id="shuffle-status">Your evening is waiting</p></div><button class="shuffle-button" id="shuffle-button" <?=$ideas?'':'disabled'?>>✦ <span class="button-label">Shuffle the deck</span> ✦</button><p class="hint">Tap once. Let anticipation do the rest.</p></section><footer><span><?=count($ideas)?> private possibilities</span><span>Made for two</span></footer></main><script>window.DATE_IDEAS=<?=json_encode($ideas,JSON_HEX_TAG|JSON_HEX_AMP|JSON_HEX_APOS|JSON_HEX_QUOT)?>;</script><script src="assets/app.js?v=1" defer></script><?php endif?></body></html>
